 61	type TraceStoreSchema =
 62	  | { readonly state: "skipped" }
 63	  | { readonly state: "migrating" }
 64	  | { readonly state: "ready"; readonly applied: readonly string[] };
 65	
 66	let traceSchema: TraceStoreSchema =
 67	  config.ingestion.role === "ingest"
 68	    ? { state: "skipped" }
 69	    : { state: "migrating" };
 70	
 71	// The carrier route this environment offers, written when the platform does
 72	// not already hold one. This is how an automated deployment configures phone
 73	// routing with no interview. In the default `platform` mode, a restart never
 74	// replaces a complete route somebody changed.
 75	const seeded = await seedPlatformSettings(config.platformSettings);
 76	
 77	// An operator can instead say that the deployment environment owns the carrier
 78	// route. Reconcile it on every start in that mode, after seeding. A changed
 79	// route replaces the stored route, and an absent route removes it. This choice
 80	// is explicit and independent of how many organizations the platform serves.
 81	const reconciled =
 82	  config.carrierSettingsSource === "environment"
 83	    ? await reconcileDeploymentCarrierSettings(config.platformSettings)
 84	    : [];
 85	
 86	// Egma-provided personas, written from the fixed-id catalog before any
 87	// project can be created or read. A new project points its default directly at
 88	// one of these rows, so provisioning must fail at start-up rather than create a
 89	// project with a missing default if the catalog cannot be written.
 90	//
 91	// Catalog edits add immutable versions and move the shared current pointer.
 92	// Old simulations keep their pinned version. A no-op boot returns no rows and
 93	// writes no log entry.
 94	const personaShelf = await seedPersonaLibrary();
 95	
 96	// egma's own graders, written onto the shelf from egma's own catalog. After the
 97	// migrations because it writes rows, and before the first request because a
 98	// project reading its Library a second later has to find them there.
 99	//
100	// Reconciliation is keyed by stable definition identifiers. A release that
101	// changes executable logic creates one immutable shared definition version and
102	// moves only the shared current pointer. Future runs pin it; old run plans keep
103	// their exact version. Project rows keep only scope and pass threshold. A
104	// release that changed nothing writes nothing at all — not even `updated_at`.
105	const graderCatalog = await reconcileGraderCatalog();
106	
107	const { app } = buildApi({
108	  config,
109	  traceStoreReady: () => traceSchema.state === "ready",
110	});
111	
112	/** The longest this process waits between attempts on the trace-store schema. */
430	 * predicate that filtered them out here would make an archived persona
431	 * unreachable by the one operation that exists to bring them back.
432	 */
433	function thePersona(auth: AuthContext, id: string): SQL {
434	  return readablePersona(auth, eq(persona.id, id));
435	}
436	
437	export type SeededPersona = {
438	  readonly id: string;
439	  readonly name: string;
440	  readonly version: number;
441	  readonly versionId: string;
442	};
443	
444	function currentCatalogVersion(entry: EgmaProvidedPersona) {
445	  const current = entry.versions.at(-1);
446	  if (current === undefined) {
447	    throw new Error(`Egma-provided persona ${entry.id} has no version`);
448	  }
449	  entry.versions.forEach((version, index) => {
450	    if (version.version !== index + 1) {
451	      throw new Error(
452	        `Egma-provided persona ${entry.id} version ${version.id} must be number ${index + 1}`,
453	      );
454	    }
455	    validateTraits(version.traits);
456	    validPersonaModels(version.models);
457	  });
458	  return current;
459	}
460	
461	/**
462	 * Put the personas Egma provides in the database without rewriting a version.
463	 * Identity metadata and the current pointer may move; version rows are insert
464	 * only and are checked byte for byte when their fixed id already exists.
465	 */
466	/** @internal Called only by the deployment seeder outside the access surface. */
467	export async function seedPersonaLibraryInternal(
468	  catalog: readonly EgmaProvidedPersona[] = PERSONA_LIBRARY_CATALOG,
469	): Promise<readonly SeededPersona[]> {
470	  if (catalog.length === 0) return [];
471	
472	  return db().transaction(async (tx) => {
473	    const seeded: SeededPersona[] = [];
474	    for (const entry of catalog) {
475	      const current = currentCatalogVersion(entry);
476	      const now = new Date();
477	      const identityInsertions = await tx
478	        .insert(persona)
479	        .values({
480	          id: entry.id,
481	          organizationId: null,
482	          projectId: null,
483	          name: entry.name,
484	          description: entry.description,
485	          currentVersionId: current.id,
486	          createdBy: null,
487	          createdAt: entry.versions[0]?.createdAt ?? current.createdAt,
488	          updatedAt: entry.versions[0]?.createdAt ?? current.createdAt,
489	        })
490	        .onConflictDoNothing({ target: persona.id })
491	        .returning({ id: persona.id });
492	      const identityUpdates =
493	        identityInsertions.length > 0
494	          ? []
495	          : await tx
496	              .update(persona)
497	              .set({
498	                name: entry.name,
499	                description: entry.description,
500	                currentVersionId: current.id,
501	                revision: newRevision(),
502	                updatedAt: now,
503	              })
504	              .where(
505	                and(
506	                  eq(persona.id, entry.id),
507	                  isNull(persona.organizationId),
508	                  sql`(${persona.name}, ${persona.description}, ${persona.currentVersionId}) is distinct from (${entry.name}, ${entry.description}, ${current.id})`,
509	                ),
510	              )
511	              .returning({ id: persona.id });
512	      const identityChanges = [...identityInsertions, ...identityUpdates];
513	      const versionInsertions = await tx
514	        .insert(personaVersion)
515	        .values(
516	          entry.versions.map((version) => ({
517	            id: version.id,
518	            personaId: entry.id,
519	            version: version.version,
520	            traits: normalizedTraits(version.traits),
521	            models: validPersonaModels(version.models),
522	            createdBy: null,
523	            createdAt: version.createdAt,
524	          })),
525	        )
526	        .onConflictDoNothing()
527	        .returning({ id: personaVersion.id });
528	
529	      const [storedIdentity] = await tx
530	        .select({
531	          organizationId: persona.organizationId,
532	          projectId: persona.projectId,
533	          name: persona.name,
534	          description: persona.description,
535	          currentVersionId: persona.currentVersionId,
536	        })
537	        .from(persona)
538	        .where(eq(persona.id, entry.id))
539	        .limit(1);
540	      if (
541	        storedIdentity === undefined ||
542	        storedIdentity.organizationId !== null ||
543	        storedIdentity.projectId !== null ||
544	        storedIdentity.name !== entry.name ||
545	        storedIdentity.description !== entry.description ||
546	        storedIdentity.currentVersionId !== current.id
547	      ) {
548	        throw new Error(
549	          `fixed Egma-provided persona id ${entry.id} already holds a different identity`,
550	        );
551	      }
552	
553	      const storedVersions = await tx
554	        .select({
555	          id: personaVersion.id,
556	          version: personaVersion.version,
557	          traits: personaVersion.traits,
558	          models: personaVersion.models,
559	        })
560	        .from(personaVersion)
561	        .where(eq(personaVersion.personaId, entry.id));
562	      for (const expected of entry.versions) {
563	        const stored = storedVersions.find((one) => one.id === expected.id);
564	        if (
565	          stored === undefined ||
566	          stored.version !== expected.version ||
567	          !sameJson(stored.traits, normalizedTraits(expected.traits)) ||
568	          !sameJson(stored.models, validPersonaModels(expected.models))
569	        ) {
570	          throw new Error(
571	            `fixed Egma-provided persona version ${expected.id} already holds different content`,
572	          );
573	        }
574	      }
575	
576	      if (identityChanges.length > 0 || versionInsertions.length > 0) {
577	        seeded.push({
578	          id: entry.id,
579	          name: entry.name,
580	          version: current.version,
581	          versionId: current.id,
582	        });
583	      }
584	    }
585	    return seeded;
